#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Projectiles;
using MVZ2.Vanilla.Audios;
using MVZ2Logic.Entities;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.freezenser)]
    public class Freezenser : DispenserFamily
    {
        public Freezenser(string nsp, string name) : base(nsp, name)
        {
        }

        public override void Init(Entity entity)
        {
            base.Init(entity);
            InitShootTimer(entity);
        }
        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);
            ShootTick(entity);
        }
        public override Entity? Shoot(Entity entity)
        {
            var projectile = base.Shoot(entity);
            if (projectile != null)
            {
                projectile.AddBuff<ChillProjectileBuff>();
                projectile.PlaySound(VanillaSoundID.snow);
            }
            return projectile;
        }
    }
}
